import {MODE_KEY,dataKey,preferenceKey,createDemoState,parseDemo,serializeDemo} from './demo.js';
import {candidateFromForm,frictionsFromForm,checkFrictionEvidence,planFromForm} from './forms.js';
import {saveState} from './storage.js?v=20261008-demo';
import {FRICTIONS,FRICTION_STATUS,frictionGuidance,blankFrictions,contextFor} from './frictions.js';
import {APP,VERSION,STAGES,KPI_KEYS,SEGMENTS,uid,today,addDays,initialState,scopeIds,metrics,alerts,followupAge,validateState,parseBackup,parseStoredState,serializeBackup,assertBackupSize,applySettings,escapeHtml as h} from './core.js';
import {TACTICS,recommendations,createPlan,existingPlan,originKey,canContact} from './tactics.js';
const $=s=>document.querySelector(s);
let pendingReview=null;
let demoMode=false,modeEpoch=0;
try{demoMode=sessionStorage.getItem(MODE_KEY)==='1';}catch{}
let state=initialState(),baseRaw=null,blocked=false,corruptRaw='',selection='scope-main',section='overview',search='',statusFilter='all',stageFilter='all',planFilter='active',importMode='backup',staleDays=21;
function recoveryView(){
 $('#recovery').innerHTML=blocked?`${demoMode?'デモの':'通常の'}保存データを読み込めませんでした。元データを上書きせず復旧してください。<div class="button-row"><button class="button" data-action="raw-export">元データを保存</button><button class="button" data-action="import">バックアップを復元</button><button class="button danger" data-action="recover-reset">${demoMode?'デモをリセット':'空データから再開'}</button></div>`:'';
}
function loadWorkspace(){
 state=demoMode?createDemoState():initialState();baseRaw=null;blocked=false;corruptRaw='';selection='scope-main';staleDays=21;
 try{
  baseRaw=localStorage.getItem(dataKey(demoMode));
  if(baseRaw!==null)state=demoMode?parseDemo(baseRaw):parseStoredState(baseRaw);
  selection=localStorage.getItem(preferenceKey('scope',demoMode))||state.scopes[0].id;
  const days=Number(localStorage.getItem(preferenceKey('stale-days',demoMode)));
  if(Number.isInteger(days)&&days>=1&&days<=365)staleDays=days;
 }catch(e){blocked=true;corruptRaw=baseRaw??'';}
 if(!state.scopes.some(s=>s.id===selection))selection=state.scopes[0].id;
 recoveryView();
}
loadWorkspace();
function resetTransient(){
 pendingReview=null;search='';statusFilter='all';stageFilter='all';planFilter='active';importMode='backup';
 $('#editor').close();$('#confirmDialog').close();$('#importFile').value='';
}
async function switchMode(next){
 if(next===demoMode)return;
 try{if(next)sessionStorage.setItem(MODE_KEY,'1');else sessionStorage.removeItem(MODE_KEY);}
 catch{throw Error('このタブのモードを保存できません。ブラウザの保存設定を確認してください');}
 modeEpoch++;demoMode=next;resetTransient();loadWorkspace();render();
 if(demoMode&&baseRaw===null&&!blocked)await commit(state);
 toast(demoMode?'デモを開始しました。すべて架空のデータです':'通常モードに戻りました。保存済みの元データを読み込みました');
}
function modeControls(){
 $('#demoBtn').textContent=demoMode?'デモ終了':'デモを試す';
 $('#exportBtn').textContent=demoMode?'デモJSONを保存':'JSONバックアップ';
 $('#demoBanner').hidden=!demoMode;
 $('#demoBanner').innerHTML=demoMode?`<strong>デモモード · すべて架空のデータ</strong><p>候補Aの入力 → 候補Bの施策・タスク・抵抗 → 会員Dの定着支援を試せます。正式実績には入りません。リセットで日付を今日基準に作り直します。</p><div class="button-row">${actionButton('demo-reset','デモをリセット','','small')}${actionButton('demo-exit','デモ終了・元データへ','','small')}</div>`:'';
 document.title=demoMode?'【デモ】NMS ACTION｜活動管理':'NMS ACTION｜活動管理';
 $('#saveStatus').textContent=demoMode?'デモ専用保存':'端末保存';
}
const labels={overview:'ホーム',tactics:'施策・実行',candidates:'候補案件',followups:'定着支援',frictions:'抵抗・対策',reviews:'振り返り',settings:'目標・設定'};
const symbols={overview:'◉',tactics:'↗',candidates:'▤',followups:'♧',frictions:'◇',reviews:'↻',settings:'⚙'};
const scopeTypes={national:'全国',regional:'地域会',branch:'支部',other:'その他'};
const statuses={active:'活動中',member:'入会済',paused:'保留',lost:'終了・辞退'};
const planStatuses={active:'進行中',deferred:'あとで',done:'完了',out:'見送る',notApplicable:'対象外',handled:'既に対応済み'};
const selected=()=>state.scopes.find(s=>s.id===selection);
const included=()=>scopeIds(state,selection);
const display=n=>n===null||n===undefined?'未設定':n.toLocaleString('ja-JP');
const dateText=d=>d||'未設定';
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function commit(next,{force=false}={}){
 const epoch=modeEpoch,mode=demoMode,key=dataKey(mode);
 await saveState({next,force,blocked,getState:()=>state,setState:value=>state=value,getRaw:()=>baseRaw,setRaw:value=>baseRaw=value,storage:localStorage,locks:navigator.locks,key,serialize:mode?serializeDemo:JSON.stringify,isCurrent:()=>epoch===modeEpoch});
 if(epoch!==modeEpoch)return;
 blocked=false;recoveryView();if(!state.scopes.some(s=>s.id===selection))selection=state.scopes[0].id;render();
 $('#saveStatus').textContent=(demoMode?'デモ保存済み ':'保存済み ')+new Date().toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'});
}
function change(fn){return commit(fn);}
function download(text,name){const u=URL.createObjectURL(new Blob([text],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function backup(){try{if(blocked)throw Error('保存データを復旧してから出力してください');const text=demoMode?serializeDemo(state):serializeBackup(state);download(text,`nms-action-${demoMode?'demo':'backup'}-${today()}.json`);toast('JSONのダウンロードを開始しました。保存先でファイルを確認してください');}catch(err){toast('バックアップを出力できません：'+err.message+'。現在のデータは保持しています');}}
function ask(title,text,onConfirm,details='',label='実行する'){const epoch=modeEpoch;title=(demoMode?'【デモ】':'')+title;const d=$('#confirmDialog');d.innerHTML=`<div class="dialog-header"><h2 id="confirmTitle">${h(title)}</h2><button type="button" data-cancel aria-label="閉じる">×</button></div><div class="dialog-body"><p>${h(text)}</p>${details?`<div class="confirm-details">${details}</div>`:''}<p class="form-error" role="alert"></p></div><div class="dialog-footer"><button class="button" data-cancel>キャンセル</button><button class="button primary" data-confirm>${h(label)}</button></div>`;d.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>d.close());d.querySelector('[data-confirm]').onclick=async()=>{const b=d.querySelector('[data-confirm]');b.disabled=true;try{if(epoch!==modeEpoch)throw Error('モードが切り替わりました。操作をやり直してください');await onConfirm();d.close();}catch(e){d.querySelector('.form-error').textContent=e.message;b.disabled=false;}};d.showModal();}
function field(name,label,value='',type='text',options={}){const {wide=false,help='',required=false,min,max}=options;return `<label class="${wide?'wide':''}">${h(label)}${required?' <span aria-hidden="true">*</span>':''}<input name="${h(name)}" type="${type}" value="${h(value??'')}" ${required?'required':''} ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''} ${type==='number'?'step="any"':''} maxlength="${type==='text'?300:2000}">${help?`<small>${h(help)}</small>`:''}</label>`;}
function area(name,label,value='',help=''){return `<label class="wide">${h(label)}<textarea name="${name}" maxlength="2000">${h(value)}</textarea>${help?`<small>${h(help)}</small>`:''}</label>`;}
function selectField(name,label,value,choices,help=''){return `<label>${h(label)}<select name="${name}">${Object.entries(choices).map(([k,v])=>`<option value="${h(k)}" ${k===value?'selected':''}>${h(v)}</option>`).join('')}</select>${help?`<small>${h(help)}</small>`:''}</label>`;}
const scopeField=(value)=>selectField('scopeId','記録する範囲',value,Object.fromEntries(state.scopes.map(s=>[s.id,`${scopeTypes[s.type]} · ${s.name}`])),'上位集計と重複する集計値を別途登録しないでください。');
function editor(title,body,onSave,{deleteFn,extra='',saveLabel='保存する'}={}){const epoch=modeEpoch;title=(demoMode?'【デモ】':'')+title;const d=$('#editor');d.innerHTML=`<form id="editForm"><div class="dialog-header"><h2 id="dialogTitle">${h(title)}</h2><button type="button" data-close aria-label="閉じる">×</button></div><div class="dialog-body">${body}<div class="form-error" role="alert" tabindex="-1"></div></div><div class="dialog-footer">${deleteFn?'<button type="button" class="button danger" data-delete>削除</button>':''}${extra}<button type="button" class="button" data-close>キャンセル</button><button type="submit" class="button primary">${h(saveLabel)}</button></div></form>`;d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());if(deleteFn)d.querySelector('[data-delete]').onclick=()=>deleteFn(d);const editedKeys=new Set();for(const event of ['input','change'])d.querySelector('form').addEventListener(event,e=>{if(e.target.name)editedKeys.add(e.target.name);});d.querySelector('form').addEventListener('invalid',e=>revealEditorField(e.currentTarget,e.currentTarget.querySelector('input:invalid,select:invalid,textarea:invalid')||e.target),true);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,submit=form.querySelector('[type=submit]');submit.disabled=true;try{if(epoch!==modeEpoch)throw Error('モードが切り替わりました。操作をやり直してください');await onSave(new FormData(form),editedKeys);d.close();toast('保存しました');}catch(err){if(err.field){const target=form.elements.namedItem(err.field);if(target){revealEditorField(form,target);}}else form.querySelectorAll('details').forEach(x=>x.open=true);const error=form.querySelector('.form-error');error.textContent=err.message;error.focus();submit.disabled=false;}};d.showModal();}

function revealEditorField(form,field){const panel=field?.closest('[data-friction-panel]');if(panel)selectFrictionPanel(form,panel.dataset.frictionPanel);revealField(field);}
function revealField(field){for(let p=field?.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;}
function selectFrictionPanel(form,kind){form.querySelectorAll('[data-friction-panel]').forEach(p=>p.hidden=p.dataset.frictionPanel!==kind);form.querySelectorAll('[data-friction-kind]').forEach(b=>{const active=b.dataset.frictionKind===kind;b.setAttribute('aria-pressed',String(active));b.classList.toggle('selected',active);});}
function contactSummary(c){const notes=[];if(c.status==='lost')notes.push('終了・辞退');if(c.status==='paused')notes.push('保留中');if(c.lastOutcome==='declined')notes.push('本人が辞退・連絡停止');if(!c.contactAllowed)notes.push('連絡可否未確認・停止');if(c.contactAfterDate)notes.push('連絡再開の合意日 '+c.contactAfterDate);if(c.contactNote)notes.push(c.contactNote);return `<div class="contact-summary ${canContact(c)?'':'warning'}"><strong>連絡制約：</strong>${h(notes.join(' ／ ')||'本人の希望する方法・時期で連絡可を確認済み')}</div>`;}
const num=(f,key)=>{const v=f.get(key);return v===''?null:Number(v);};
const txt=(f,key)=>String(f.get(key)??'').trim();
function heading(eyebrow,title,description,action=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function empty(title,text,action=''){return `<div class="empty"><div class="empty-icon">＋</div><h3>${title}</h3><p>${text}</p>${action}</div>`;}
function actionButton(action,label,id='',cls=''){return `<button class="button ${cls}" data-action="${action}" data-id="${h(id)}">${label}</button>`;}
function candidateBadges(c){return alerts(c).map(a=>`<span class="badge ${a.kind}">${h(a.text)}</span>`).join('');}
function recommendationCard(r){return `<div class="action-item"><div><span class="badge">${h(r.candidate.alias)}</span><strong class="break"> ${h(r.tactic.title)}</strong><p>${h(r.reason)}</p>${r.candidate.segments.length?`<p>分類：${h(r.candidate.segments.join('・'))}</p>`:''}</div>${actionButton(r.existing?'plan-edit':'recommend',r.existing?'計画へ':'内容を見る',r.existing?r.existing.id:r.candidate.id,'small')}</div>`;}
function todayActions(ids){
 const cases=state.candidates.filter(c=>ids.has(c.scopeId)&&c.status==='active'&&c.nextAction&&c.dueDate&&c.dueDate<=today());
 const tasks=state.campaigns.filter(p=>ids.has(p.scopeId)&&p.status==='active').flatMap(p=>p.tasks.filter(t=>!t.done&&t.dueDate&&t.dueDate<=today()).map(t=>({p,t})));
 return `<section class="card today-actions"><div class="section-head"><h2>今日やること</h2><span class="count">${cases.length+tasks.length}件 · 期限超過を含む</span></div>${cases.map(c=>`<div class="action-item"><div><strong>${h(c.nextAction)}</strong><p>${h(c.alias)} ／ ${h(c.owner||'担当未設定')} ／ ${h(c.dueDate)}</p>${!canContact(c)?contactSummary(c):''}</div>${actionButton('candidate-edit','確認',c.id,'small')}</div>`).join('')}${tasks.map(({p,t})=>{const c=state.candidates.find(c=>c.id===p.candidateId);return `<div class="action-item"><div><strong>${h(t.title)}</strong><p>${h(c?.alias)} ／ ${h(t.owner||'担当未設定')} ／ ${h(t.dueDate)}</p>${c&&!canContact(c)?contactSummary(c):''}</div>${actionButton('plan-edit','計画へ',p.id,'small')}</div>`;}).join('')}${cases.length+tasks.length?'':empty('今日が期限の行動はありません','候補案件の「次の行動」と期限を入れると、ここに表示します。')}</section>`;
}
function overview(){const m=metrics(state,selection),s=m.scope;const net=m.officeJoins-m.officeLeaves;const progress=m.current===null||s.targetOffices===null||s.baselineOffices===null||s.targetOffices<=s.baselineOffices?0:Math.min(100,Math.max(0,(m.current-s.baselineOffices)/(s.targetOffices-s.baselineOffices)*100));const issues=state.candidates.filter(c=>m.ids.has(c.scopeId)&&alerts(c).length);const recs=recommendations(state,m.ids,today(),staleDays);return heading('ACTIVITY OVERVIEW','今日の一手を、成果につなぐ。',`${h(s.name)}の目標と活動をまとめて確認できます。`,actionButton('candidate-new','＋ 候補案件'))+(!s.dueDate||s.targetOffices===null?`<div class="info-banner">まず対象範囲の基準日・件数・目標・期日を設定してください。全国目標と地域・支部目標は個別に扱います。 ${actionButton('scope-edit','目標を設定',s.id,'small')}</div>`:'')+todayActions(m.ids)+`<section class="card"><div class="section-head"><h2>次に取り組む施策</h2>${actionButton('nav-tactics','すべての施策','','small')}</div>${recs.length?recs.slice(0,3).map(recommendationCard).join(''):empty('状況に応じて、施策がここに届きます','候補案件を登録すると、段階・実参加日・フォロー状況から理由付きでおすすめします。',actionButton('nav-tactics','施策ライブラリを見る','','small'))}</section><div class="overview-checks"><section class="card"><div class="section-head"><h2>いま確認したいこと</h2><span class="count">${issues.length}件</span></div>${issues.length?issues.slice(0,5).map(c=>`<div class="action-item"><div><strong>${h(c.alias)}</strong><p>${h(c.nextAction||'次の行動を決める')} ／ ${h(c.owner||'主担当未設定')}</p><div class="badges">${candidateBadges(c)}</div></div>${actionButton('candidate-edit','確認',c.id,'small')}</div>`).join(''):empty('確認待ちの案件はありません','候補案件の担当・次の行動・期限をそろえましょう。')}</section></div><details class="analytics-details"><summary>目標の進捗・段階別の分析を見る</summary><section class="hero" aria-label="目標進捗"><div><p class="eyebrow">OFFICE GROWTH</p><h2>事務所数の純増目標</h2><div class="hero-number">${display(m.current)}<small>／ ${display(s.targetOffices)} 事務所</small></div><div class="progress"><span style="--progress:${progress}%"></span></div><p>基準 ${h(s.baselineDate)}：${display(s.baselineOffices)}事務所　目標期日 ${h(dateText(s.dueDate))}</p><div class="hero-meta"><span>確定入会 ＋${m.officeJoins}事務所</span><span>確定退会 −${m.officeLeaves}事務所</span></div></div><div class="hero-right"><p class="eyebrow">NEXT MILESTONE</p><h2>目標までの残り</h2><div class="hero-number">${display(m.remaining)}<small>事務所</small></div><p>新規入会人数の目標：${display(s.newMembersTarget)}人<br>確認済みの新規入会：${m.peopleJoins}人<br>未入会の候補案件は実績に含めません。</p>${actionButton('event-new','＋ 確定実績を記録','','small')}</div></section><div class="stat-grid"><div class="card stat"><span class="label">事務所の純増</span><b class="value ${net<0?'negative':'positive'}">${net>0?'+':''}${net}</b><small>入会 − 退会 ／ 事務所</small></div><div class="card stat"><span class="label">未入会・活動中（1案件＝1人）</span><b class="value">${m.active.length}</b><small>重複分類は1案件として集計</small></div><div class="card stat"><span class="label">要確認の案件</span><b class="value ${issues.length?'negative':''}">${issues.length}</b><small>期限・担当・支援の確認</small></div><div class="card stat"><span class="label">進行中の施策</span><b class="value">${state.campaigns.filter(p=>m.ids.has(p.scopeId)&&p.status==='active').length}</b><small>タスク完了と実績は別記録</small></div></div><p class="metrics-explanation">集計期間：基準日の翌日〜${m.end}。選択範囲と下位範囲の確定記録を1回ずつ集計。基準事務所数は選択範囲の設定値を使用します。</p><section class="card"><div class="section-head"><h2>未入会案件の現在段階</h2><span class="count">現在在籍数</span></div><div class="pipeline">${KPI_KEYS.map(k=>`<div class="pipeline-row"><span>${k} ${STAGES[k]}</span><div class="pipeline-track"><div style="--progress:${m.active.length?m.stages[k]/m.active.length*100:0}%"></div></div><span class="pipeline-num">${m.stages[k]}人 / ${m.required[k]===null?'—':m.required[k]}人</span></div>`).join('')}</div><div class="help">左は現在段階の人数、右は残りの新規入会人数目標 × 設定倍率を切り上げた目安。面談前 ${m.stages.K0}件はK5に含めません。段階の到達累計や成約確率ではありません。</div></section></details>`;}
function candidatesView(){const ids=included();const list=state.candidates.filter(c=>ids.has(c.scopeId)&&(statusFilter==='all'||c.status===statusFilter)&&(stageFilter==='all'||c.stage===stageFilter)&&[c.alias,c.owner,c.helpers,c.issue,c.nextAction].join(' ').toLowerCase().includes(search.toLowerCase()));return heading('CANDIDATE PIPELINE','候補案件','面談前から入会後まで、担当と次の行動をひと目で。',actionButton('candidate-new','＋ 候補案件'))+`<div class="toolbar"><input id="search" aria-label="案件を検索" placeholder="呼び名・担当・課題で検索" value="${h(search)}"><select id="statusFilter" aria-label="案件状況"><option value="all">すべての状況</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${k===statusFilter?'selected':''}>${v}</option>`).join('')}</select><select id="stageFilter" aria-label="案件段階"><option value="all">すべての段階</option>${Object.entries(STAGES).map(([k,v])=>`<option value="${k}" ${k===stageFilter?'selected':''}>${k} ${v}</option>`).join('')}</select></div><div class="candidate-grid">${list.map(caseCard).join('')}</div>${list.length?'':empty(state.candidates.length?'該当する案件がありません':'最初の一件から始めましょう','呼び名は匿名の案件コードでも登録できます。必須入力を軽くし、あとから詳しく追記できます。',actionButton('candidate-new','候補案件を登録','','primary'))}`;}
function caseCard(c){return `<article class="card case-card"><div class="case-top"><div><span class="badge">${c.status==='active'?`${c.stage} ${STAGES[c.stage]}`:statuses[c.status]}</span><h2>${h(c.alias)}</h2></div>${!c.contactAllowed?'<span class="badge late">連絡可否未確認・停止</span>':''}</div><div class="case-meta"><span>${h(state.scopes.find(s=>s.id===c.scopeId)?.name)}</span><span>担当 ${h(c.owner||'未設定')}</span></div>${c.segments.length?`<div class="badges">${c.segments.map(s=>`<span class="badge">${h(s)}</span>`).join('')}</div>`:''}<div class="case-action"><small>次の行動</small><p>${h(c.nextAction||'次の一手を決めましょう')}</p></div><div class="badges">${candidateBadges(c)}</div><div class="case-footer"><span>期限 ${h(dateText(c.dueDate))}</span>${actionButton('candidate-edit','編集',c.id,'small')}</div><div class="button-row">${actionButton('friction-edit','抵抗を確認',c.id,'small')}${actionButton('recommend','施策を選ぶ',c.id,'small')}</div></article>`;}
function followupsView(){const ids=included();const list=state.candidates.filter(c=>ids.has(c.scopeId)&&c.status==='member');return heading('MEMBER SUPPORT','入会後の定着を支える','3回の実施と、その先の支援方針を確認します。',actionButton('candidate-new','＋ 対象者'))+`<div class="info-banner">入会後概ね3年以内をフォローの目安として表示します。3回終了や3年経過による自動削除・支援終了は行いません。入会済の登録と、確定入会実績の記録は別です。</div><div class="candidate-grid">${list.map(c=>`<article class="card case-card"><div class="case-top"><h2>${h(c.alias)}</h2><span class="badge">${followupAge(c)}</span></div><p class="card-sub">入会 ${h(c.joinedDate)} ／ バディ ${h(c.buddy||'未設定')}</p><div class="follow-progress">${c.followups.map((f,i)=>`<div class="follow-step ${f.completedDate?'done':''}">第${i+1}回<br>${f.completedDate?'実施 '+h(f.completedDate):'予定 '+h(dateText(f.plannedDate))}</div>`).join('')}</div><div class="badges">${candidateBadges(c)}</div><p class="card-sub break">${h(c.riskReason||'相談内容・継続支援方針を記録しましょう。')}</p><div class="button-row">${actionButton('recommend','支援施策',c.id,'small')}${actionButton('candidate-edit','支援を記録',c.id,'small primary')}</div></article>`).join('')}</div>${list.length?'':empty('入会後の対象者はまだありません','案件を「入会済」にして入会日を登録すると、3回フォローを記録できます。')}`;}
function reviewsView(){const ids=included(),list=state.reviews.filter(r=>ids.has(r.scopeId)).sort((a,b)=>b.date.localeCompare(a.date));return heading('AFTER ACTION REVIEW','振り返りを、次の行動へ','期待・実際・理由を整理し、変えることを一つ決めます。',actionButton('review-new','＋ 振り返り'))+`<div class="review-grid">${list.map(r=>`<article class="card"><div class="section-head"><div><h2>${h(r.title)}</h2><p class="card-sub">${h(r.date)} ／ ${h(r.owner||'担当未設定')} ${r.candidateId?'／ '+h(state.candidates.find(c=>c.id===r.candidateId)?.alias):''}</p></div>${actionButton('review-edit','編集',r.id,'small')}</div><div class="review-lines"><div><small>期待していたこと</small><p>${h(r.plan||'—')}</p></div><div><small>実際に起きたこと</small><p>${h(r.actual||'—')}</p></div><div><small>差の理由・学び</small><p>${h(r.learning||'—')}</p></div><div><small>次に変えること · ${h(dateText(r.dueDate))}</small><p>${h(r.nextAction||'—')}</p></div></div></article>`).join('')}</div>${list.length?'':empty('活動を次の一手につなげましょう','訪問や見学会の結果から、一つの改善行動を残します。',actionButton('review-new','振り返りを記録','','primary'))}`;}
function tacticsView(){const ids=included(),recs=recommendations(state,ids,today(),staleDays),plans=state.campaigns.filter(p=>ids.has(p.scopeId)&&(planFilter==='all'||p.status===planFilter));return heading('STRATEGY INTO ACTION','施策を選び、動き出す。','理由を確かめて採用し、担当・期限付きの計画へ落とし込みます。')+`<div class="info-banner">以下は方針に基づく、編集できるアプリ提案です。質問文・手順・7日以外の日数は公式ルールではありません。本人の連絡停止・辞退・約束・指定日を優先してください。費用・条件・サービス内容は最新情報を個別に確認します。</div><section class="card"><div class="section-head"><h2>状況からのおすすめ</h2><span class="count">候補先ごと1件</span></div>${recs.length?recs.map(recommendationCard).join(''):empty('おすすめ待ちです','案件の状況を記録すると、連絡制約を確認して候補を提示します。')}</section><div class="section-head" style="margin-top:28px"><h2>採用した実行計画</h2><select id="planFilter" aria-label="実行計画の状況" style="width:160px"><option value="all">すべて</option>${Object.entries(planStatuses).map(([k,v])=>`<option value="${k}" ${k===planFilter?'selected':''}>${v}</option>`).join('')}</select></div><div class="candidate-grid">${plans.map(p=>`<article class="card"><div class="case-top"><h2>${h(p.title)}</h2><span class="badge">${planStatuses[p.status]}</span></div><p class="card-sub">${h(state.candidates.find(c=>c.id===p.candidateId)?.alias||'対象なし')} ／ ${h(p.owner)}<br>期限 ${h(dateText(p.dueDate))} · テンプレート v${p.templateVersion}</p><fieldset><legend>実行タスク ${p.tasks.filter(t=>t.done).length}/${p.tasks.length}</legend><div class="stack">${p.tasks.map(t=>`<label class="checks"><input type="checkbox" data-task="${t.id}" data-plan="${p.id}" ${t.done?'checked':''}><span class="break">${h(t.title)}<small>${h(t.owner||'担当未設定')} ／ ${h(dateText(t.dueDate))}${!t.done&&t.dueDate&&t.dueDate<today()?' · 期限超過':''}</small></span></label>`).join('')}</div></fieldset><p class="card-sub">効果指標：${h(p.metric)}<br>目標 ${p.target} ／ 確認結果 ${p.actual===null?'未記録':p.actual}</p><div class="button-row">${p.status==='done'?actionButton('review-from-plan','振り返り',p.id,'small'):''}${p.status==='done'&&p.nextTacticId?actionButton('plan-next','次の施策',p.id,'small'):''}${actionButton('plan-edit','編集・結果記録',p.id,'small primary')}</div></article>`).join('')}</div>${plans.length?'':empty('この状況の計画はありません','施策を採用すると、3〜5件のタスクをまとめて作れます。')}<div class="section-head" style="margin-top:28px"><h2>12の施策ライブラリ</h2><span class="count">質問・準備・完了条件つき</span></div><div class="candidate-grid">${TACTICS.map(t=>`<article class="card"><p class="eyebrow">${t.id}</p><h2>${h(t.title)}</h2><p class="card-sub">${h(t.purpose)}</p><p class="card-sub">対象：${h(t.who)}</p><div class="button-row">${actionButton('tactic-detail','詳細・採用',t.id,'small')}</div></article>`).join('')}</div>`;}
function settingsView(){const s=selected(),m=metrics(state,selection);const events=state.events.filter(e=>m.ids.has(e.scopeId)).sort((a,b)=>b.date.localeCompare(a.date));return heading('GOALS & DATA','目標とデータの設定','対象の範囲・単位・期間をそろえて、数字を確かめます。')+`<div class="settings-grid"><section class="card"><div class="section-head"><h2>対象範囲と目標</h2>${actionButton('scope-new','＋ 範囲','','small')}</div>${state.scopes.map(x=>`<div class="scope-item"><div><strong>${h(x.name)}</strong><small>${scopeTypes[x.type]}${x.parentId?' ／ 上位 '+h(state.scopes.find(y=>y.id===x.parentId)?.name):' ／ 上位なし'}</small><small>${h(x.baselineDate)} 基準 ${display(x.baselineOffices)} → ${display(x.targetOffices)}事務所<br>新規入会 ${display(x.newMembersTarget)}人 ／ ${h(dateText(x.dueDate))}</small></div>${actionButton('scope-edit','編集',x.id,'small')}</div>`).join('')}<div class="help">上位範囲は下位の確定入退会記録を1回ずつ集計します。上位の基準件数・目標は別設定です。全国数値を地域・支部の目標へ流用しないでください。</div></section><div class="stack"><section class="card"><h2>バックアップと復元</h2><p class="card-sub">入力内容はこのブラウザに保存されます。別端末への移動はJSONバックアップを使います。復元すると現在のデータ全体を置き換えます。</p><div class="button-row">${actionButton('export','JSONを保存','','small')}${actionButton('import','JSONを復元','','small')}${demoMode?'':actionButton('settings-import','設定JSONを読み込む','','small')}</div><p class="card-sub">設定JSONは対象範囲のみを変更。案件に紐づく範囲を消す設定は拒否します。バックアップには入力した情報が含まれるため、共有先に注意してください。</p></section><section class="card"><h2>おすすめの目安</h2><label>停滞と表示する接点経過日数<input id="staleDays" type="number" min="1" max="365" step="1" value="${staleDays}"><small>21日は編集できるアプリ目安です。無限の再連絡を生成しません。</small></label><div class="button-row">${actionButton('stale-save','目安を保存','','small')}</div></section><section class="card"><h2>このアプリの使い方</h2><p class="card-sub">①目標設定 → ②候補登録 → ③施策採用 → ④担当・期限を確認 → ⑤結果・実績を記録 → ⑥振り返り。実績を先に確かめ、段階を更新してください。</p><div class="button-row">${actionButton('reset','全データを初期化','','small danger')}</div></section></div></div><section class="card" style="margin-top:24px"><div class="section-head"><h2>確定入退会の実績台帳</h2>${actionButton('event-new','＋ 実績','','small')}</div><p class="card-sub">案件ステータスやタスクチェックから自動登録されません。基準日以前・未来日・目標期日後の記録は、この目標期間の進捗から除外します。</p>${events.length?`<div class="table-wrap"><table><thead><tr><th>実績日</th><th>対象コード</th><th>範囲</th><th>区分</th><th>事務所</th><th>人数</th><th>操作</th></tr></thead><tbody>${events.map(e=>`<tr><td>${h(e.date)}</td><td>${h(e.entityKey)}</td><td>${h(state.scopes.find(s=>s.id===e.scopeId)?.name)}</td><td>${e.kind==='join'?'入会':'退会'}</td><td>${e.offices}</td><td>${e.people}</td><td>${actionButton('event-edit','編集',e.id,'small')}</td></tr>`).join('')}</tbody></table></div>`:empty('確定実績はまだありません','対象コード・日付・事務所数・人数を確認して記録します。')}</section>`;}
function render(){modeControls();section=location.hash.slice(1);if(!labels[section])section='overview';$('#nav').innerHTML=Object.entries(labels).map(([k,v])=>`<a href="#${k}" class="${section===k?'active':''}" ${section===k?'aria-current="page"':''}><span class="nav-symbol" aria-hidden="true">${symbols[k]}</span>${v}</a>`).join('');$('#scopeSelect').innerHTML=state.scopes.map(s=>`<option value="${s.id}" ${s.id===selection?'selected':''}>${h(s.name)}</option>`).join('');$('#main').innerHTML=({overview,candidates:candidatesView,followups:followupsView,frictions:frictionsView,reviews:reviewsView,tactics:tacticsView,settings:settingsView}[section])();}
function newCandidate(){return {id:uid(),alias:'',scopeId:selection,owner:'',helpers:'',segments:[],stage:'K0',stageSince:today(),meetingDate:'',lastOutcome:'unknown',lastContactDate:'',status:'active',issue:'',nextAction:'',dueDate:'',visitDate:'',closeVisitDate:'',joinedDate:'',buddy:'',risk:'low',riskReason:'',contactAllowed:false,contactAfterDate:'',contactNote:'',followups:Array.from({length:3},()=>({plannedDate:'',completedDate:'',note:''}))};}
function editCandidate(id){const old=state.candidates.find(c=>c.id===id),c=structuredClone(old||newCandidate());const body=`<p class="card-sub">まずは呼び名だけで登録できます。主担当・次の行動・期限は分かる範囲で。1案件は1人、匿名コードをおすすめします。</p><div class="form-grid">${field('alias','呼び名・案件コード',c.alias,'text',{required:true,help:'実名や個人連絡先を入れずに運用できます。'})}${field('owner','主担当',c.owner)}${selectField('stage','現在段階（事実確認後に更新）',c.stage,Object.fromEntries(Object.entries(STAGES).map(([k,v])=>[k,`${k} ${v}`])),'K5：面談実施、K4：課題の本人確認、K3：提案提示、K2：実参加、K1：クローズ活動。')}${area('nextAction','次の行動・本人との約束',c.nextAction)}${field('dueDate','次の行動期限・合意日',c.dueDate,'date')}</div>${contactSummary(c)}<details class="form-details"><summary>所属・分類・経緯などの詳細</summary><div class="form-grid">${scopeField(c.scopeId)}${field('helpers','協力者',c.helpers)}${selectField('status','状況',c.status,statuses)}${field('stageSince','段階の確認日',c.stageSince,'date')}${field('lastContactDate','最終接点の実施日',c.lastContactDate,'date')}${field('meetingDate','本人と合意した初回面談予定日',c.meetingDate,'date')}${selectField('lastOutcome','本人の検討状況',c.lastOutcome||'unknown',{unknown:'未確認',continue:'検討継続',unsuccessful:'不成功（再連絡可否を別途確認）',declined:'本人が辞退・連絡停止'})}<fieldset class="wide"><legend>分類（複数可・人数は重複しません）</legend><div class="checks">${SEGMENTS.map(s=>`<label><input type="checkbox" name="segments" value="${s}" ${c.segments.includes(s)?'checked':''}>${s}</label>`).join('')}</div></fieldset>${area('issue','本人と確認した課題',c.issue)}${field('visitDate','見学会の実参加日',c.visitDate,'date',{help:'参加予定・欠席は入力しません。実参加日＋7暦日で確認。'})}${field('closeVisitDate','見学後クローズ訪問の実施日',c.closeVisitDate,'date')}${field('joinedDate','確認済みの入会日',c.joinedDate,'date',{help:'実績台帳への算入は別途記録が必要です。'})}</div></details><details class="form-details"><summary>連絡制約・辞退・保留を変更</summary><fieldset><legend>連絡制約（施策のおすすめより優先）</legend><label class="checks"><input type="checkbox" name="contactAllowed" ${c.contactAllowed?'checked':''}>本人の希望する方法・時期で連絡できることを確認済み</label><div class="form-grid" style="margin-top:16px">${field('contactAfterDate','連絡再開の合意日（それまでは保留）',c.contactAfterDate,'date')}${area('contactNote','本人の希望・辞退・日程制約',c.contactNote)}</div></fieldset></details><details class="form-details"><summary>入会後の支援・3回の記録</summary><fieldset><legend>入会後フォロー（入会済の方）</legend><div class="form-grid">${field('buddy','バディ・支援窓口',c.buddy)}${selectField('risk','本人の相談・支援優先度',c.risk,{low:'通常',watch:'要確認・相談あり',high:'優先支援・退会懸念'})}${area('riskReason','相談内容・継続支援方針',c.riskReason,'活動が少ないだけで退会懸念と判断しないでください。')}${c.followups.map((f,i)=>`<fieldset class="wide"><legend>第${i+1}回支援</legend><div class="form-grid">${field(`followPlan${i}`,'予定日',f.plannedDate,'date')}${field(`followDone${i}`,'実施日',f.completedDate,'date')}${area(`followNote${i}`,'支援内容・結果',f.note)}</div></fieldset>`).join('')}</div></fieldset></details>`;
 editor(old?'候補案件を編集':'候補案件を登録',body,async (f,editedKeys)=>{const out=candidateFromForm(c,f,editedKeys);for(const k of ['lastContactDate','visitDate','closeVisitDate','joinedDate'])if(out[k]>today())throw Error('実施日・入会日に未来日は登録できません');if(out.followups.some(x=>x.completedDate>today()))throw Error('支援実施日に未来日は登録できません');await change(s=>{if(old)s.candidates=s.candidates.map(x=>x.id===out.id?out:x);else s.candidates.push(out);});},{deleteFn:old?d=>ask('案件を削除しますか',`「${old.alias}」と関連する実行計画を削除します。実績台帳は保持し、振り返りとの関連を解除します。必要なら先にバックアップしてください。`,async()=>{await change(s=>{s.candidates=s.candidates.filter(x=>x.id!==id);s.campaigns=s.campaigns.filter(x=>x.candidateId!==id);s.reviews.forEach(r=>{if(r.candidateId===id)r.candidateId='';});});d.close();toast('案件を削除しました');},'','削除する'):undefined});}
function editScope(id){const old=state.scopes.find(s=>s.id===id);const s=structuredClone(old||{...initialState().scopes[0],id:uid(),name:'',parentId:selection});const exclude=old?scopeIds(state,id):new Set();const parents={'':'上位なし',...Object.fromEntries(state.scopes.filter(x=>!exclude.has(x.id)).map(x=>[x.id,x.name]))};const body=`<div class="form-grid">${field('name','範囲名',s.name,'text',{required:true})}${selectField('type','範囲種別',s.type,scopeTypes)}${selectField('parentId','上位の範囲',s.parentId,parents)}${field('baselineDate','基準日',s.baselineDate,'date',{required:true,help:'基準日時点の件数。翌日からの実績を加減します。'})}${field('baselineOffices','基準事務所数',s.baselineOffices,'number',{min:0,max:10000000})}${field('targetOffices','目標事務所数',s.targetOffices,'number',{min:0,max:10000000})}${field('newMembersTarget','新規入会人数の目標',s.newMembersTarget,'number',{min:0,max:10000000,help:'事務所数とは別の人数目標。純増目標との差を退会見込みと解釈しません。'})}${field('dueDate','目標期日',s.dueDate,'date')}</div><fieldset><legend>入会1人に必要な未入会人数の倍率（任意設定）</legend><p class="card-sub">残り新規入会人数 × 各倍率を切り上げて表示。倍率を段階間で乗算せず、成約確率にも使いません。現在段階の在籍数との比較目安です。</p><div class="form-grid">${KPI_KEYS.map(k=>field(k,`${k} ${STAGES[k]}`,s.ratios[k],'number',{min:0,max:1000})).join('')}</div></fieldset>`;editor(old?'対象範囲と目標を編集':'対象範囲を追加',body,async f=>{const out={...s};for(const k of ['name','type','parentId','baselineDate','dueDate'])out[k]=txt(f,k);for(const k of ['baselineOffices','targetOffices','newMembersTarget'])out[k]=num(f,k);out.ratios=Object.fromEntries(KPI_KEYS.map(k=>[k,num(f,k)]));await change(v=>{if(old)v.scopes=v.scopes.map(x=>x.id===id?out:x);else v.scopes.push(out);});},{deleteFn:old?d=>ask('対象範囲を削除しますか',`「${s.name}」を削除します。下位範囲や記録がある場合は削除できません。`,async()=>{if(state.scopes.length===1||state.scopes.some(x=>x.parentId===id)||[...state.candidates,...state.events,...state.reviews,...state.campaigns].some(x=>x.scopeId===id))throw Error('唯一の範囲、下位範囲・記録のある範囲は削除できません');await change(v=>v.scopes=v.scopes.filter(x=>x.id!==id));d.close();},'','削除する'):undefined});}
function editEvent(id){const old=state.events.find(e=>e.id===id),e=old||{id:uid(),entityKey:'',scopeId:selection,date:today(),kind:'join',offices:1,people:1,confirmed:false,note:''};editor(old?'確定実績を編集':'確定入退会を記録',`<div class="info-banner warning">ここは実績の確認記録です。案件ステータスや施策の完了を実績とみなしません。実績対象のコードをそろえ、集計値を二重登録しないでください。</div><div class="form-grid">${field('entityKey','対象コード',e.entityKey,'text',{required:true,help:'同じ対象・日付・区分の重複登録を拒否します。'})}${scopeField(e.scopeId)}${field('date','確認した入退会日',e.date,'date',{required:true})}${selectField('kind','区分',e.kind,{join:'入会',leave:'退会'})}${field('offices','事務所件数',e.offices,'number',{min:0,max:10000})}${field('people','人数',e.people,'number',{min:0,max:10000,help:'既存事務所への追加人員なら事務所件数は0。'})}${area('note','確認根拠・メモ',e.note)}<label class="checks wide"><input type="checkbox" name="confirmed" required ${e.confirmed?'checked':''}>入退会の事実と事務所数・人数を確認しました</label></div>`,async f=>{if(txt(f,'date')>today())throw Error('確定実績に未来日は登録できません');const out={...e,entityKey:txt(f,'entityKey'),scopeId:txt(f,'scopeId'),date:txt(f,'date'),kind:txt(f,'kind'),offices:num(f,'offices'),people:num(f,'people'),confirmed:f.has('confirmed'),note:txt(f,'note')};await change(s=>{if(old)s.events=s.events.map(x=>x.id===id?out:x);else s.events.push(out);});},{deleteFn:old?d=>ask('実績を削除しますか','この記録を削除すると目標の集計が変わります。',async()=>{await change(s=>s.events=s.events.filter(x=>x.id!==id));d.close();},'','削除する'):undefined});}
function editReview(id){const old=state.reviews.find(r=>r.id===id),r=old||pendingReview||{id:uid(),scopeId:selection,candidateId:'',date:today(),title:'',owner:'',plan:'',actual:'',learning:'',nextAction:'',dueDate:''};pendingReview=null;editor(old?'振り返りを編集':'活動の振り返り',`<div class="form-grid">${field('title','活動名',r.title,'text',{required:true})}${scopeField(r.scopeId)}${field('date','活動実施日',r.date,'date',{required:true})}${field('owner','改善行動の担当',r.owner)}${selectField('candidateId','関連する案件',r.candidateId,{'':'関連なし',...Object.fromEntries(state.candidates.map(c=>[c.id,c.alias]))})}${field('dueDate','改善行動の期限',r.dueDate,'date')}${area('plan','期待していたこと',r.plan)}${area('actual','実際に起きたこと（事実）',r.actual)}${area('learning','差の理由・学び（事実と仮説を分ける）',r.learning)}${area('nextAction','次に変えることを一つ',r.nextAction)}</div>`,async f=>{if(txt(f,'date')>today())throw Error('活動実施日に未来日は登録できません');const out={...r};for(const k of Object.keys(r).filter(k=>k!=='id'))out[k]=txt(f,k);await change(s=>{if(old)s.reviews=s.reviews.map(x=>x.id===id?out:x);else s.reviews.push(out);});},{deleteFn:old?d=>ask('振り返りを削除しますか',`「${r.title}」を削除します。`,async()=>{await change(s=>s.reviews=s.reviews.filter(x=>x.id!==id));d.close();},'','削除する'):undefined});}
function tacticDetail(tid,cid=''){const t=TACTICS.find(t=>t.id===tid),c=state.candidates.find(c=>c.id===cid);const r=c?recommendations(state,new Set([c.scopeId]),today(),staleDays).find(r=>r.candidate.id===cid&&r.tactic.id===tid):null;const reason=r?.reason||'ライブラリから手動で選択';const body=`${c?`<p class="badge">対象：${h(c.alias)}</p><p class="card-sub">推薦理由：${h(reason)}</p>`:''}<p class="card-sub">${h(t.purpose)}<br>対象：${h(t.who)}</p><ol>${t.tasks.map(x=>`<li style="font-size:13px;line-height:2">${h(x)}</li>`).join('')}</ol><div class="help"><strong>質問例</strong><p>${h(t.question)}</p><button type="button" class="button small" data-copy>質問をコピー</button></div><p class="card-sub"><strong>準備物：</strong>${h(t.prep)}<br><strong>担当役割：</strong>${h(t.role)}<br><strong>期限：</strong>${tid==='P06'?'実参加日＋7暦日。参加日がなければ本人との合意日':tid==='P10'?'入会後7/30/60日は編集可能な仮初期値':tid==='P05'?'実在イベント開催日。未定なら情報待ち':tid==='P07'?'本人との再提案の合意日':t.days===null?'適任者確認3日、その後は合意日':`採用後${t.days}日（編集可能なアプリ目安）`}<br><strong>完了条件：</strong>${h(t.completion)}<br><strong>次の施策：</strong>${h(t.next)}</p><div class="form-grid">${selectField('candidateId','対象案件を選ぶ',cid,{'':'選択してください',...Object.fromEntries(state.candidates.filter(c=>included().has(c.scopeId)).map(c=>[c.id,c.alias]))})}${selectField('disposition','扱い', 'active',{active:'採用して実行計画を作る',deferred:'あとで（計画を保留）',out:'見送る',notApplicable:'対象外',handled:'既に対応済み'})}</div><p class="card-sub">採用済みの手順は版を保持します。チェックだけで案件段階・面談・入会実績を自動変更しません。</p>`;editor(`${t.id} ${t.title}`,body,async f=>{const chosen=state.candidates.find(x=>x.id===txt(f,'candidateId'));if(!chosen)throw Error('対象案件を選んでください');const existing=existingPlan(state,chosen,t);if(existing)throw Error('同じ施策の進行中・保留中の計画があります。キャンセルして既存計画を開いてください');const completed=state.campaigns.some(p=>p.candidateId===chosen.id&&p.tacticId===t.id&&p.originKey===originKey(chosen,t)&&['done','handled','out','notApplicable'].includes(p.status));if(completed)throw Error('同じ起点で対応済みです。既存計画の編集から明示的に再開できます');const p=createPlan(chosen,t,reason);p.status=txt(f,'disposition');await change(s=>s.campaigns.push(p));setTimeout(()=>planSummary(p.id),0);},{saveLabel:'選択した扱いで保存'});$('#editor').querySelector('[data-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(t.question);toast('質問例をコピーしました');}catch{toast('コピーできません。表示された質問文を選択してください');}};}
function planSummary(id){
 const p=state.campaigns.find(p=>p.id===id);if(!p)return;const c=state.candidates.find(c=>c.id===p.candidateId),d=$('#editor');
 d.innerHTML=`<div class="dialog-header"><h2 id="dialogTitle">${demoMode?'【デモ】':''}実行計画を保存しました</h2><button type="button" data-close aria-label="閉じる">×</button></div><div class="dialog-body"><h3>${h(p.title)}</h3><p class="card-sub">${h(c?.alias)} ／ ${h(p.owner||'担当未設定')}<br>期限 ${h(dateText(p.dueDate))} ／ ${h(planStatuses[p.status])}</p>${c?contactSummary(c):''}<h3>${p.status==='active'?'次に取り組むこと':'保存した手順'}</h3><ol class="task-summary">${p.tasks.filter(t=>!t.done).map(t=>`<li>${h(t.title)}<small>${h(t.owner||'担当未設定')} ／ ${h(dateText(t.dueDate))}</small></li>`).join('')}</ol><p class="card-sub">登録済みの担当・期限を引き継ぎました。実績・入会・段階は事実を確認して別途記録します。</p></div><div class="dialog-footer"><button type="button" class="button" data-details>詳細・期限を調整</button><button type="button" class="button primary" data-close>確認しました</button></div>`;
 d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());d.querySelector('[data-details]').onclick=()=>{d.close();editPlan(id);};d.showModal();
}
function editPlan(id){const p=structuredClone(state.campaigns.find(p=>p.id===id));if(!p)return;const c=state.candidates.find(c=>c.id===p.candidateId);const body=`<p class="card-sub">対象 ${h(c?.alias)} ／ ${p.tacticId}・テンプレート v${p.templateVersion}<br>採用理由：${h(p.reason)}</p>${p.tacticId==='P06'&&p.originKey.startsWith('visit:')&&p.originKey.slice(6)?`<div class="info-banner">元の実参加 ${h(p.originKey.slice(6))} ／ 7日確認期限 ${h(addDays(p.originKey.slice(6),7))}。期限を過ぎていても消しません。本人の希望日が異なる場合は結果・理由を記録してください。</div>`:''}${c&&!c.contactAllowed?'<div class="info-banner warning">対象案件は連絡停止です。本人への連絡タスクを実行せず、保留・対象外を選んでください。</div>':''}<div class="form-grid">${field('owner','計画の担当',p.owner)}${field('dueDate','全体の期限（合意日）',p.dueDate,'date')}${selectField('status','計画の状況',p.status,planStatuses)}</div><details class="form-details"><summary>指標・タスクごとの担当と期限・結果を編集</summary><div class="form-grid">${field('metric','効果を確認する指標',p.metric)}${field('target','指標の目標',p.target,'number',{min:0,max:10000000})}${field('actual','確認した実際の結果（未確認は空欄）',p.actual,'number',{min:0,max:10000000})}${selectField('nextTacticId','結果に応じた次の施策',p.nextTacticId||'',{'':'未選択',...Object.fromEntries(TACTICS.map(t=>[t.id,t.title]))})}</div>${p.tasks.map((t,i)=>`<fieldset><legend>タスク${i+1}</legend><div class="form-grid">${field(`taskTitle${i}`,'実行すること',t.title,'text',{wide:true,required:true})}${field(`taskOwner${i}`,'担当',t.owner)}${field(`taskDue${i}`,'期限',t.dueDate,'date')}<label class="checks wide"><input type="checkbox" name="taskDone${i}" ${t.done?'checked':''}>タスクを完了（実績確認とは別）</label></div></fieldset>`).join('')}<div class="form-grid">${p.frictionSnapshot?.length?`<div class="help wide"><strong>採用時の本人確認済みの根拠</strong>${p.frictionSnapshot.map(f=>`<p>${h(FRICTIONS[f.kind].label)}：${h(f.answer)}<br>確認 ${h(f.confirmedDate)} ／ ${h(f.confirmedBy)}<br>実制約：${h(f.actualConstraint||'未確認')}<br>合意対応：${h(f.agreedAction||'未設定')}<br>再確認：${h(f.recheckQuestion)}</p>`).join('')}</div>`:''}${p.templateSnapshot?`<div class="help wide">採用時の完了条件：${h(p.templateSnapshot.completion)}<br>次の施策：${h(p.templateSnapshot.next)}</div>`:''}${area('reflection','結果・学び・本人の意思',p.reflection)}${area('nextAction','次の施策・改善行動',p.nextAction)}<label class="checks wide"><input type="checkbox" name="completionConfirmed">完了にする場合：施策の完了条件と記録を確認しました</label></div><div class="help">見学後の期限は元の実参加日＋7日を保ってください。本人の希望日が異なる場合は理由を結果欄へ残します。日付未定は情報待ちです。入会や段階は事実を確認して別途更新します。</div></details>`;editor('実行計画・結果を編集',body,async (f,editedKeys)=>{const out=planFromForm(p,f,editedKeys);const originalDeadline=p.tacticId==='P06'&&p.originKey.startsWith('visit:')?addDays(p.originKey.slice(6),7):'';if(originalDeadline&&out.dueDate!==originalDeadline&&!out.reflection)throw Error('元の7日期限と異なる日を設定する場合は本人の希望・理由を結果欄に記録してください');if(out.status==='done'&&(!f.has('completionConfirmed')||!out.reflection||!out.nextAction))throw Error('完了条件の確認、結果・学び、次の一手を記録してください');if(c&&!canContact(c)&&p.tacticId!=='P12'&&(out.status==='active'||out.tasks.some((t,i)=>t.done&&!p.tasks[i].done)))throw Error('連絡制約のある対象は保留または対象外を選んでください');await change(s=>s.campaigns=s.campaigns.map(x=>x.id===id?out:x));},{deleteFn:d=>ask('実行計画を削除しますか','タスクと結果記録を削除します。案件と実績台帳は保持します。',async()=>{await change(s=>s.campaigns=s.campaigns.filter(x=>x.id!==id));d.close();},'','削除する')});}
function frictionsView(){const ids=included(),list=state.candidates.filter(c=>ids.has(c.scopeId));return heading('FRICTION THEORY','4つの抵抗を確かめる','仮説から始め、本人の回答を確かめて、対応と再確認につなげます。')+`<div class="info-banner">惰性・労力・感情・心理的反発は、Nordgren / Schonthal『The Human Element』の枠組みです。段階別の質問と対策は本アプリの応用提案で、著者やTKCが認定した診断尺度ではありません。人の性格や属性から判断しません。費用・時間・不適合や拒否は、合理的な制約・意思として尊重します。<br>出典：<a href="https://www.humanelementbook.com/" target="_blank" rel="noopener noreferrer">著者公式</a> · <a href="https://www.soshisha.com/book_search/detail/1_2624.html" target="_blank" rel="noopener noreferrer">草思社の邦訳紹介</a></div><div class="stat-grid">${Object.values(FRICTIONS).map(f=>`<div class="card stat"><h2>${h(f.label)}</h2><p class="card-sub">${h(f.description)}</p></div>`).join('')}</div><div class="candidate-grid">${list.map(c=>`<article class="card"><h2>${h(c.alias)}</h2><p class="card-sub">確認する場面：${h(contextLabels[contextFor(c)])}</p><div class="stack">${frictionGuidance(c).map(g=>{const f=(c.frictions||[]).find(f=>f.kind===g.kind);return `<div><span class="badge">${g.label} · ${h(f?FRICTION_STATUS[f.status]:'未確認')}${f?.context&&f.context!==contextFor(c)?'（旧段階・再確認が必要）':''}</span><p class="card-sub">仮説：${h(g.hypothesis)}<br>質問：${h(g.question)}</p></div>`;}).join('')}</div><div class="button-row">${actionButton('friction-edit','本人の回答と対応を記録',c.id,'small primary')}${actionButton('recommend','施策につなげる',c.id,'small')}</div></article>`).join('')}</div>${list.length?'':empty('候補案件から、一つの問いを選びましょう','4分類を毎回すべて質問する必要はありません。必要な一つから本人に確認します。')}`;}
const contextLabels={K0:'面談前',K5:'面談・接点づくり',K4:'課題の共通認識',K3:'課題に沿った提案',K2:'見学会・セミナー',K1:'意思確認・クロージング',ONBOARDING:'入会後3回支援',RETENTION:'継続支援・退会懸念への対応'};
function editFrictions(id){
 const c=state.candidates.find(c=>c.id===id),context=contextFor(c);
 const fs=blankFrictions().map(f=>({...f,...c.frictions?.find(x=>x.kind===f.kind)}));
 const defaults=fs.map(f=>({...f,context:f.context||context,confirmedBy:f.confirmedBy||c.owner}));
 const first=fs.find(f=>['hypothesis','confirmed','addressed','recheck'].includes(f.status))?.kind||fs[0].kind;
 const body=`<p class="card-sub">${h(c.alias)} ／ 今の場面：${h(contextLabels[context])}<br>必要な問い一つを選んで記録します。未返信や経過日数は確認根拠にしません。</p>${contactSummary(c)}<div class="pill-nav" aria-label="確認する抵抗">${fs.map(f=>`<button type="button" class="button small ${f.kind===first?'selected':''}" data-friction-kind="${f.kind}" aria-pressed="${f.kind===first}">${h(FRICTIONS[f.kind].label)} · ${h(FRICTION_STATUS[f.status])}</button>`).join('')}</div>${frictionGuidance(c).map(g=>{
 const f=defaults.find(f=>f.kind===g.kind),k=g.kind;
 return `<section data-friction-panel="${k}" ${k===first?'':'hidden'}><div class="help"><strong>${h(g.label)}：今回の問い</strong><p>${h(g.question)}</p><details><summary>仮説・対応案・再確認のガイド</summary><p>仮説：${h(g.hypothesis)}<br>対応案：${h(g.action)}<br>対応候補：${h(TACTICS.find(t=>t.id===g.tacticId).title)}<br>再確認：${h(g.recheck)}</p></details></div><div class="form-grid" style="margin-top:16px">${selectField(`${k}Status`,'確認状況',f.status,FRICTION_STATUS)}${field(`${k}ReviewDate`,'本人との再確認予定日',f.reviewDate,'date')}${area(`${k}Answer`,'本人の回答・発言',f.answer)}${area(`${k}Action`,'本人と合意した小さな対応',f.agreedAction)}</div><details class="form-details"><summary>確認の根拠・段階・詳しい記録</summary><p class="card-sub">本人確認済みには回答・確認日・確認者・段階が必要です。費用・時間・不適合は実際の制約として扱い、見送りや拒否を尊重します。</p><div class="form-grid">${selectField(`${k}Context`,'確認した段階',f.context,contextLabels)}${field(`${k}Date`,'本人確認日',f.confirmedDate,'date')}${field(`${k}By`,'確認した担当者',f.confirmedBy)}${area(`${k}Fact`,'観察した事実と担当の仮説（区別して記録）',f.fact)}${area(`${k}Constraint`,'実際の費用・時間・条件などの制約',f.actualConstraint)}${selectField(`${k}Tactic`,'対応に使う施策',f.tacticId,{'':'未選択',...Object.fromEntries(TACTICS.map(t=>[t.id,`${t.id} ${t.title}`]))})}${field(`${k}RecheckedDate`,'本人と再確認した実施日',f.recheckedDate,'date')}${area(`${k}Result`,'本人と確認した結果・残る課題',f.reviewResult)}</div></details></section>`;
 }).join('')}<p class="card-sub">本人確認済みの記録だけを、その段階の推薦へ反映します。段階が変わったら再確認し、対応の実施だけで解消済みにしません。</p>`;
 editor('本人の回答と次の対応',body,async(f,editedKeys)=>{const out=frictionsFromForm(c.frictions,defaults,f,editedKeys);checkFrictionEvidence(out,today());await change(s=>s.candidates.find(x=>x.id===id).frictions=out);});
 const form=$('#editForm');form.querySelectorAll('[data-friction-kind]').forEach(b=>b.onclick=()=>selectFrictionPanel(form,b.dataset.frictionKind));
}

function recommend(id){const c=state.candidates.find(c=>c.id===id);const r=recommendations(state,new Set([c.scopeId]),today(),staleDays).find(r=>r.candidate.id===id);if(r?.existing){editPlan(r.existing.id);return;}if(r){tacticDetail(r.tactic.id,id);return;}editor('案件に合わせて施策を選ぶ',`<p class="card-sub">${h(c.alias)}：連絡制約・対応済み・情報不足を確認してください。本人の希望が最優先です。</p><div class="form-grid">${selectField('tacticId','施策',TACTICS[0].id,Object.fromEntries(TACTICS.map(t=>[t.id,t.title])))}</div>`,f=>setTimeout(()=>tacticDetail(txt(f,'tacticId'),id),0),{saveLabel:'詳細を見る'});}
const actions={
 'demo-start':()=>ask('デモを開始しますか','架空データで機能を試します。通常データは保持し、このタブだけデモに切り替えます。',()=>switchMode(true),'','デモ開始'),
 'demo-exit':()=>switchMode(false),
 'demo-reset':()=>ask('デモをリセットしますか','デモでの編集だけを消し、架空データと日付を今日基準に作り直します。通常データは保持します。',async()=>{if(!demoMode)throw Error('デモモードで操作してください');await commit(createDemoState(),{force:blocked});toast('デモをリセットしました');},'','デモをリセット'),
 'candidate-new':()=>editCandidate(), 'candidate-edit':editCandidate,'scope-new':()=>editScope(),'scope-edit':editScope,'event-new':()=>editEvent(),'event-edit':editEvent,'review-new':()=>editReview(),'review-edit':editReview,'tactic-detail':tacticDetail,'recommend':recommend,'plan-next':id=>{const p=state.campaigns.find(p=>p.id===id);tacticDetail(p.nextTacticId,p.candidateId);},'review-from-plan':id=>{const p=state.campaigns.find(p=>p.id===id);pendingReview={id:uid(),scopeId:p.scopeId,candidateId:p.candidateId,date:today(),title:p.title+'の振り返り',owner:p.owner,plan:p.metric+'：目標 '+p.target,actual:p.reflection,learning:'',nextAction:p.nextAction,dueDate:''};editReview();},'plan-edit':editPlan,'friction-edit':editFrictions,
 'nav-tactics':()=>location.hash='tactics','export':backup,'raw-export':()=>download(corruptRaw,demoMode?'nms-action-demo-damaged.json':'nms-action-damaged-backup.json'),
 'import':()=>{importMode='backup';$('#importFile').value='';$('#importFile').click();},'settings-import':()=>{if(demoMode)throw Error('設定JSONは通常モードで読み込んでください');importMode='settings';$('#importFile').value='';$('#importFile').click();},
 'stale-save':()=>{const n=Number($('#staleDays').value);if(!Number.isInteger(n)||n<1||n>365)throw Error('目安は1〜365日の整数にしてください');localStorage.setItem(preferenceKey('stale-days',demoMode),String(n));staleDays=n;render();toast('おすすめの目安を保存しました');},
 'reset':()=>demoMode?actions['demo-reset']():ask('全データを初期化しますか','目標、案件、実績、実行計画、振り返りを削除します。必要なら先にJSONバックアップを保存してください。',async()=>{await commit(initialState(),{force:blocked});toast('初期化しました');},'','初期化する'),
 'recover-reset':()=>demoMode?actions['demo-reset']():ask('空データから再開しますか','読み込めなかった保存データを置き換えます。必要なら「元データを保存」で退避してください。',async()=>{await commit(initialState(),{force:true});toast('空データから再開しました');},'','再開する')
};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{await actions[b.dataset.action]?.(b.dataset.id);}catch(err){toast(err.message);}});
$('#exportBtn').onclick=backup;
$('#demoBtn').onclick=async()=>{try{await actions[demoMode?'demo-exit':'demo-start']();}catch(err){toast(err.message);}};
$('#scopeSelect').onchange=e=>{selection=e.target.value;try{localStorage.setItem(preferenceKey('scope',demoMode),selection);}catch{}render();};
$('#main').addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
$('#main').addEventListener('change',async e=>{if(e.target.id==='statusFilter'){statusFilter=e.target.value;render();}if(e.target.id==='stageFilter'){stageFilter=e.target.value;render();}if(e.target.id==='planFilter'){planFilter=e.target.value;render();}if(e.target.dataset.task){try{const p=state.campaigns.find(x=>x.id===e.target.dataset.plan),c=state.candidates.find(x=>x.id===p.candidateId);if(e.target.checked&&p.tacticId!=='P12'&&c&&!canContact(c))throw Error('連絡制約を確認してからタスクを実行してください');const checked=e.target.checked;await change(s=>s.campaigns.find(x=>x.id===p.id).tasks.find(t=>t.id===e.target.dataset.task).done=checked);toast('タスクを保存しました（実績は別記録）');}catch(err){e.target.checked=!e.target.checked;toast(err.message);}}});
$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;const epoch=modeEpoch,mode=demoMode,kind=importMode;try{assertBackupSize(file.size);const text=await file.text();if(epoch!==modeEpoch)throw Error('モードが切り替わりました。ファイルを選び直してください');let next;if(kind==='settings'){if(mode)throw Error('設定JSONは通常モードで読み込んでください');next=applySettings(state,JSON.parse(text));}else next=mode?parseDemo(text,{backup:true}):parseBackup(text);const info=`対象範囲 ${next.scopes.length}／案件 ${next.candidates.length}／実績 ${next.events.length}／施策 ${next.campaigns.length}／振り返り ${next.reviews.length}`;ask(kind==='settings'?'設定を読み込みますか':'バックアップを復元しますか',kind==='settings'?'対象範囲・目標を置き換えます。案件・実績・施策は保持します。':'現在のデータ全体を置き換えます。取り消しに必要な現在のJSONを先に保存してください。',async()=>{await commit(next,{force:blocked});toast('JSONを読み込みました');},h(info),'読み込む');}catch(err){toast('読み込めません：'+err.message);}};
window.addEventListener('hashchange',()=>{search='';render();});
window.addEventListener('storage',e=>{if((e.key===dataKey(demoMode)||e.key===null)&&e.newValue!==baseRaw)toast('別タブで変更されました。再読み込みして最新データを確認してください');});
render();

